def extract_texts(path):
    prs = Presentation(path)
    result = []
    for i, slide in enumerate(prs.slides, start=1):
        buf = []
        for shape in slide.shapes:
            if hasattr(shape, "text") and shape.text:
                buf.append(shape.text)
        if getattr(slide, "has_notes_slide", False):
            notes = slide.notes_slide.notes_text_frame
            if notes and notes.text:
                buf.append(notes.text)
        result.append({"slide_number": i, "text": " ".join(buf).strip()})
    return result

slides = extract_texts(pptx_path)
for s in slides:
    print(f"Slide {s['slide_number']}: {s['text']}\n")
